function updateOverview(){const online=equipment.filter(d=>d.online).length,used=rooms.filter(r=>r.occupied).length,pending=alerts.filter(a=>!a.resolved);$('.online-stat b').innerHTML=(online/equipment.length*100).toFixed(1)+'<small>%</small>';$('.ring b').innerHTML=Math.round(used/rooms.length*100)+'<small>%</small>';$('.count').textContent=pending.length+' 项待关注';$('.scene-status').innerHTML=`<i></i> 校园整体运行 <span>${pending.length?pending.length+' 项异常待关注':'当前无待处理告警'}</span>`;$('#deviceRows').innerHTML=[['light','☼','智慧照明','LIGHTING'],['camera','◉','视频监控','CAMERA'],['access','⌑','门禁系统','ACCESS'],['sensor','❖','环境传感器','SENSOR']].map(([type,icon,name,en])=>{let ds=equipment.filter(d=>d.type===type),on=ds.filter(d=>d.online).length;return `<button class="device device-summary" data-kind="${type}"><span>${icon}</span><div><b>${name}</b><small>${en}</small></div><label><strong>${on} 在线</strong><small>${ds.length-on} 离线 · ${ds.filter(d=>d.online&&d.running).length} ${type==='access'?'解锁':type==='light'?'开启':'运行'}</small></label></button>`}).join('');document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{const ds=equipment.filter(d=>d.type===b.dataset.kind),d=ds.find(x=>!x.online)||ds[0];openBuilding(d.bi,'devices');if(d.room)currentRoom=rooms.find(r=>r.id===d.room);deviceFilter=d.online?'all':'offline';focusBuilding(d.bi,d.id);renderDetail()});$('.events-panel').querySelectorAll('.alert').forEach((b,i)=>{const a=alerts[i];b.classList.toggle('resolved',a.resolved);b.querySelector('.alert-type').childNodes[0].textContent=a.resolved?'✓ 已恢复 ':a.title+' ';b.querySelector('time').textContent=a.resolved?'本次会话':a.ack?'已确认':i?'2 分钟前':'刚刚';if(a.resolved)b.querySelector('small').innerHTML='状态已恢复正常<span class="locate">查看 ↗</span>';else if(i===0)b.querySelector('small').innerHTML='<strong>32.6<sub>°C</sub></strong><span class="alert-desc">超出阈值 2.6°C</span><span class="locate">定位 ↗</span>'});labels[0].el.classList.toggle('warn',!alerts[0].resolved);labels[0].el.textContent=(!alerts[0].resolved?'◉ ':'')+data[0][0];const badge=$('#buildings button small');badge.textContent=alerts[0].resolved?'查看 →':'● 预警'}
$('#buildings').innerHTML=data.map((r,i)=>`<button data-id="${i}"><span>▧</span>${r[0]}<small>${i===0?'● 预警':'查看 →'}</small></button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openBuilding(+b.dataset.id));document.querySelectorAll('[data-focus]').forEach((b,i)=>b.onclick=()=>openAlert(alerts[i].id));
$('#reset').onclick=()=>{$('.left').scrollTop=0;$('.right').scrollTop=0;desiredTarget.set(0,0,0);desiredRadius=285;angle=.72;elevation=.83;$('#detail').hidden=true;marker.visible=false;highlight.visible=false;beacon.visible=false;selected=-1;document.querySelectorAll('#buildings button').forEach(b=>b.classList.remove('selected'))};$('#rotate').onclick=()=>{auto=!auto;$('#rotate').classList.toggle('on',auto);toast(auto?'已开始校园自动巡航':'已暂停自动巡航')};$('#alarm').onclick=()=>{if(alerts[0].resolved){alerts[0].resolved=false;alerts[0].ack=false;hotRoom.temp=32.6;updateOverview()}openAlert('heat')};$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('当前环境不支持全屏'))};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.body.dataset.view=b.dataset.tab;if(b.dataset.tab==='devices'){openBuilding(0,'devices')}else if(b.dataset.tab==='energy'){$('.energy-panel').scrollIntoView({behavior:'smooth',block:'start'});toast('当前展示今日模拟用电趋势')}else $('#reset').click()});updateOverview();
let down=false,moved=false,last={x:0,y:0};renderer.domElement.addEventListener('pointerdown',e=>{down=true;moved=false;last={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;angle-=dx*.006;elevation=T.MathUtils.clamp(elevation+dy*.004,.25,1.35);last={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{down=false;if(moved)return;let p=new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),ray=new T.Raycaster();ray.setFromCamera(p,camera);let hit=ray.intersectObjects(buildings,true)[0];if(hit)select(hit.object.userData.id)});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();desiredRadius=T.MathUtils.clamp(desiredRadius+e.deltaY*.15,110,460)},{passive:false});renderer.domElement.style.touchAction='none';window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});function clock(){$('#clock').textContent=new Date().toLocaleString('zh-CN',{hour12:false})}clock();setInterval(clock,1000);setInterval(()=>$('#temp').innerHTML=(24.8+(Math.random()-.5)*.4).toFixed(1)+'<small>°C</small>',6000);function animate(t){requestAnimationFrame(animate);if(auto)angle+=.0012;target.lerp(desiredTarget,.045);radius+=(desiredRadius-radius)*.045;camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*radius,target.y+Math.sin(elevation)*radius,target.z+Math.cos(angle)*Math.cos(elevation)*radius);camera.lookAt(target);marker.material.opacity=.5+Math.sin(t*.003)*.3;beacon.scale.setScalar(1+Math.sin(t*.003)*.18);camera.updateMatrixWorld();labels.forEach(({el,p},i)=>{let q=p.clone().project(camera);el.style.left=(q.x*.5+.5)*innerWidth+'px';el.style.top=(-q.y*.5+.5)*innerHeight+'px';el.style.display=q.z>1||q.x<-1||q.x>1||(![0,2,4].includes(i)&&i!==selected)?'none':'block'});renderer.render(scene,camera)}animate(0);
